import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter/foundation.dart';

import '../models/enums.dart';
import '../models/registration.dart';

/// Mirrors every registration to Firestore so it can be checked there.
///
/// Individuals go to `users`, shelters / restaurants / companies go to
/// `partners`. Each document id is auto-generated by Firestore. Passwords are
/// never part of a [Registration], so no credentials are stored.
class RegistrationRemote {
  RegistrationRemote._();

  static final _db = FirebaseFirestore.instance;

  static String collectionFor(RegistrationKind kind) =>
      kind.isPartner ? 'partners' : 'users';

  /// A fresh, unique, auto-generated document id for [kind].
  static String newId(RegistrationKind kind) =>
      _db.collection(collectionFor(kind)).doc().id;

  /// Creates or updates the document of [r] with its complete info.
  static Future<void> save(Registration r) async {
    try {
      await _db.collection(collectionFor(r.kind)).doc(r.id).set({
        ...r.toJson(),
        'uid': r.ownerId,
        'type': r.kind.isPartner ? 'partner' : 'user',
        'displayName': r.displayName,
        'createdAt': Timestamp.fromDate(r.createdAt),
        'reviewedAt': r.reviewedAt == null
            ? null
            : Timestamp.fromDate(r.reviewedAt!),
        'updatedAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));
    } catch (e) {
      debugPrint('Firestore save failed for ${r.id}: $e');
    }
  }
}
